  [6281] = { "Proseguire per Stormwind", "Compra un volo in grifone dal maestro dei grifoni Thor, poi porta la Lewis' Note a Osric Strang, nella bottega Limited Immunity, nella Old Town di Stormwind.", "Per una piccola somma puoi prendere un grifone per Stormwind, così potrai consegnare il biglietto di Lewis a Osric. In nessun altro modo arriverai prima.\n\nSe ti sta bene, parlami di nuovo quando sei <pronto/pronta> per il volo. Ti chiederò qualcosa, ma fidati: ne varrà la pena!", "Sei in viaggio, eh? Sei <stato/stata> in qualche posto interessante?", "Ah, un biglietto da Quartermaster Lewis? Non mi stupisce che gli serva altra attrezzatura. Sentinel Hill è lontana, in una terra che Stormwind ha quasi dimenticato.\n\nBe', grazie, {name}. Ecco un po' di denaro per coprire le spese di viaggio.", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
